package br.com.sussmartcare.triage.infrastructure.ai; import br.com.sussmartcare.triage.application.RiskAssessmentPort; import br.com.sussmartcare.triage.domain.ClinicalPriority; import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker; import io.github.resilience4j.retry.annotation.Retry; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component @ConditionalOnProperty(name="ai.provider",havingValue="http") public class HttpRiskAssessmentAdapter implements RiskAssessmentPort {private final RestClient client;public HttpRiskAssessmentAdapter(RestClient.Builder b,@Value("${ai.base-url:http://localhost:8091}")String base){client=b.baseUrl(base).build();}
 @CircuitBreaker(name="triageAi",fallbackMethod="fallback") @Retry(name="triageAi") public RiskAssessmentResult assess(RiskAssessmentRequest r){var result=client.post().uri("/internal/v1/risk-assessments").body(r).retrieve().body(RiskAssessmentResult.class);if(result==null)throw new IllegalStateException("AI provider retornou resposta vazia");return result;}
 public RiskAssessmentResult fallback(RiskAssessmentRequest r,Throwable error){return new RiskAssessmentResult(ClinicalPriority.MEDIUM,0.0,"AI_UNAVAILABLE_FALLBACK: usar regras institucionais e classificação profissional.","fallback","1.0",true);}}
